{
  "cases": [
    {
      "id": "C1",
      "instrument_review": "MESA distinguishes evidence of repeated testing from evidence of stability. Neither is established by one reported run when repetition is unspecified.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish variation across repeated runs."
        }
      ]
    },
    {
      "id": "C2",
      "instrument_review": "MESA treats the explicit absence of repetition as evidence that repeated testing did not occur. Score stability remains unknown.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "The passage explicitly rules out repeated evaluations."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "Without repeated results, stability is unmeasured; this does not establish instability."
        }
      ]
    },
    {
      "id": "C3",
      "instrument_review": "MESA separates whether repetition occurred from what it found. Repetition occurred, and the observed range meets the report's stated stability criterion.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The evaluation was repeated under unchanged stated conditions and score variation was reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed two-percentage-point range meets the stated criterion for this comparison."
        }
      ]
    },
    {
      "id": "C4",
      "instrument_review": "MESA counts repeated testing even when results are unfavourable. The observed variation fails the report's stability criterion.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations under unchanged stated conditions measured score variation."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed range exceeds the explicitly defined stability limit."
        }
      ]
    },
    {
      "id": "C5",
      "instrument_review": "Under MESA, installation documentation helps describe access and setup but supplies no evidence of repeated testing or score stability.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repetition remains unspecified; installation instructions do not establish that testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The new documentation supplies no repeated scores from which stability could be assessed."
        }
      ]
    },
    {
      "id": "C6",
      "instrument_review": "MESA supports interpreting the observed comparison within its stated grid-puzzle scope. The evidence does not establish a ranking in general intelligence.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more evaluated puzzles under the stated scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The results provide no evidence establishing comparative general intelligence across domains."
        }
      ]
    },
    {
      "id": "C7",
      "instrument_review": "MESA identifies a gap between the broad intended use and the narrow evidence. Stating a general-intelligence selection purpose does not validate that inference.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The observed counts support A's better performance on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The intended use extends across domains, but the supplied findings do not."
        }
      ]
    },
    {
      "id": "C8",
      "instrument_review": "MESA distinguishes initial test scores from later evidence about workshop decisions. The trial supports correctness for the studied conditions, while safety remains unmeasured.",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone supply no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%. The reported uncertainty interval for the difference was 12 to 28 percentage points.",
          "reason": "The randomized trial found higher correctness with A, with the reported difference interval favouring A in the studied workshop."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not by itself establish improved workplace safety."
        }
      ]
    }
  ],
  "closing_note": "No instructions were unclear. Missing evidence was distinguished from explicit contradiction, and no aggregate score was calculated."
}
